/**
 * Shared gh CLI command-string helpers for the gh-* enforcer hooks — #3389.
 *
 * Zero network calls, zero file I/O — pure flag parsing, same budget as the
 * enforcers that import it.
 */

/**
 * True when the command explicitly targets a repository via `--repo`/`-R`
 * or a `GH_REPO=` env prefix.
 *
 * The enforcers are pure flag parsers with no network or file I/O, so they
 * cannot know whether an explicit target is this project or a foreign repo.
 * An explicit target is therefore out of scope: label and milestone
 * taxonomies are repo-local, and enforcing this project's vocabulary on
 * another repo ranges from noise (a nudge about our sprint milestones) to
 * breakage (`--label bug` fails outright on a repo without that label).
 * Observed 2026-08-10: an issue filed to a third-party repo was hard-denied
 * for missing a label from OUR taxonomy (#3389).
 */
export function hasExplicitRepoTarget(command: string): boolean {
  return /(^|[\s;|&])(--repo|-R)[=\s]+\S+/.test(command) || /(^|[\s;|&])GH_REPO=\S+/.test(command);
}

/**
 * Ordered, first-match-wins. docs outranks bug so "fix typo in README"
 * lands as docs, not bug.
 */
const LABEL_PATTERNS: ReadonlyArray<readonly [RegExp, string]> = [
  [/\b(docs?|documentation|readme|typo)\b/, 'docs'],
  [/\b(fix(es|ed)?|bug|error|crash(es)?|broken|regress(es|ion|ed)?|fail(s|ing|ure)?)\b/, 'bug'],
  [/\b(feat(ure)?|add(s|ed)?|support|implement(s|ed|ation)?|improve(s|d|ment)?|enhance(s|d|ment)?)\b/, 'enhancement'],
];

/**
 * Infer a default label for `gh issue create` from its --title value,
 * falling back to scanning the whole command when no title is present.
 * 'chore' is the safe default: every governed repo's taxonomy has it.
 */
export function inferIssueLabel(command: string): string {
  const m = /--title[=\s]+(?:"([^"]*)"|'([^']*)'|(\S+))/.exec(command);
  const title = (m?.[1] ?? m?.[2] ?? m?.[3] ?? command).toLowerCase();
  for (const [pattern, label] of LABEL_PATTERNS) {
    if (pattern.test(title)) return label;
  }
  return 'chore';
}
